1474.     pub open spec fn next_step(self, s: ClusterState, s_prime: ClusterState, step: Step) -> bool {
1475.         match step {
1476.             Step::APIServerStep(input) => self.api_server_next().forward(input)(s, s_prime),
1477.             Step::BuiltinControllersStep(input) => self.builtin_controllers_next().forward(input)(s, s_prime),
1478.             Step::ControllerStep(input) => self.controller_next().forward(input)(s, s_prime),
1479.             Step::ScheduleControllerReconcileStep(input) => self.schedule_controller_reconcile().forward(input)(s, s_prime),
1480.             Step::RestartControllerStep(input) => self.restart_controller().forward(input)(s, s_prime),
1481.             Step::DisableCrashStep(input) => self.disable_crash().forward(input)(s, s_prime),
1482.             Step::DropReqStep(input) => self.drop_req().forward(input)(s, s_prime),
1483.             Step::DisableReqDropStep => self.disable_req_drop().forward(())(s, s_prime),
1484.             Step::PodMonkeyStep(input) => self.pod_monkey_next().forward(input)(s, s_prime),
1485.             Step::DisablePodMonkeyStep => self.disable_pod_monkey().forward(())(s, s_prime),
1486.             Step::ExternalStep(input) => self.external_next().forward(input)(s, s_prime),
1487.             Step::StutterStep => self.stutter().forward(())(s, s_prime),
1488.         }
1489.     }
