1491.     pub open spec fn api_server_next(self) -> Action<ClusterState, Option<Message>, ()> {
1492.         let result = |input: Option<Message>, s: ClusterState| {
1493.             let host_result = self.api_server().next_result(
1494.                 APIServerActionInput{ recv: input },
1495.                 s.api_server
1496.             );
1497.             let msg_ops = MessageOps {
1498.                 recv: input,
1499.                 send: host_result->Enabled_1.send,
1500.             };
1501.             let network_result = network().next_result(msg_ops, s.network);
1502. 
1503.             (host_result, network_result)
1504.         };
1505.         Action {
1506.             precondition: |input: Option<Message>, s: ClusterState| {
1507.                 &&& received_msg_destined_for(input, HostId::APIServer)
1508.                 &&& result(input, s).0 is Enabled
1509.                 &&& result(input, s).1 is Enabled
1510.             },
1511.             transition: |input: Option<Message>, s: ClusterState| {
1512.                 let (host_result, network_result) = result(input, s);
1513.                 (ClusterState {
1514.                     api_server: host_result->Enabled_0,
1515.                     network: network_result->Enabled_0,
1516.                     ..s
1517.                 }, ())
1518.             },
1519.         }
