1920. pub open spec fn resp_msg_matches_req_msg(resp_msg: Message, req_msg: Message) -> bool {
1921.     ||| {
1922.         &&& resp_msg.content is APIResponse
1923.         &&& req_msg.content is APIRequest
1924.         &&& resp_msg.dst == req_msg.src
1925.         &&& resp_msg.src == req_msg.dst
1926.         &&& resp_msg.rpc_id == req_msg.rpc_id
1927.         &&& match resp_msg.content->APIResponse_0 {
1928.             APIResponse::GetResponse(_) => req_msg.content->APIRequest_0 is GetRequest,
1929.             APIResponse::ListResponse(_) => req_msg.content->APIRequest_0 is ListRequest,
1930.             APIResponse::CreateResponse(_) => req_msg.content->APIRequest_0 is CreateRequest,
1931.             APIResponse::DeleteResponse(_) => req_msg.content->APIRequest_0 is DeleteRequest,
1932.             APIResponse::UpdateResponse(_) => req_msg.content->APIRequest_0 is UpdateRequest,
1933.             APIResponse::UpdateStatusResponse(_) => req_msg.content->APIRequest_0 is UpdateStatusRequest,
1934.             APIResponse::GetThenDeleteResponse(_) => req_msg.content->APIRequest_0 is GetThenDeleteRequest,
