2232. pub open spec fn reconcile_core(v_replica_set: VReplicaSetView, resp_o: Option<ResponseView<VoidERespView>>, state: VReplicaSetReconcileState) -> (VReplicaSetReconcileState, Option<RequestView<VoidEReqView>>) {
2233.     let namespace = v_replica_set.metadata.namespace.unwrap();
2234.     match &state.reconcile_step {
2235.         VReplicaSetRecStepView::Init => {
2236.             if v_replica_set.metadata.deletion_timestamp.is_some() {
2237.                 let state_prime = VReplicaSetReconcileState {
2238.                     reconcile_step: VReplicaSetRecStepView::Done,
2239.                     ..state
2240.                 };
2241.                 (state_prime, None)
2242.             } else {
2243.                 let req = APIRequest::ListRequest(ListRequest {
2244.                     kind: PodView::kind(),
2245.                     namespace: namespace,
2246.                 });
2247.                 let state_prime = VReplicaSetReconcileState {
2248.                     reconcile_step: VReplicaSetRecStepView::AfterListPods,
2249.                     ..state
2250.                 };
2251.                 (state_prime, Some(RequestView::KRequest(req)))
2252.             }
2253.         },
2254.         VReplicaSetRecStepView::AfterListPods => {
2255.             let predicate1 = ( resp_o is Some && resp_o.unwrap() is KResponse && resp_o.unwrap().arrow_KResponse_0() is ListResponse);
2256.             let predicate2 = resp_o.unwrap().arrow_KResponse_0().arrow_ListResponse_0().res;
2257. 
2258.             if !(predicate1 && predicate2 is Ok) {
2259.                 (error_state(state), None)
2260.             } else {
2261.                 let objs = predicate2.unwrap();
2262.                 let pods_or_none = objects_to_pods(objs);
2263.                 if pods_or_none.is_none() {
2264.                     (error_state(state), None)
2265.                 } else {
2266.                     let pods = pods_or_none.unwrap();
2267.                     let filtered_pods = filter_pods(pods, v_replica_set);
2268.                     let replicas = v_replica_set.spec.replicas.unwrap_or(0);
2269.                     if replicas < 0 {
2270.                         (error_state(state), None)
2271.                     } else {
2272.                         let desired_replicas = replicas;
2273.                         if filtered_pods.len() == desired_replicas {
2274.                             let state_prime = VReplicaSetReconcileState {
2275.                                 reconcile_step: VReplicaSetRecStepView::Done,
2276.                                 ..state
2277.                             };
2278.                             (state_prime, None)
2279.                         } else if filtered_pods.len() < desired_replicas {
2280.                             let diff =  desired_replicas - filtered_pods.len();
2281.                             let pod = make_pod(v_replica_set);
2282.                             let req = APIRequest::CreateRequest(CreateRequest {
2283.                                 namespace: namespace,
2284.                                 obj: pod.marshal(),
2285.                             });
2286.                             let state_prime = VReplicaSetReconcileState {
2287.                                 reconcile_step: VReplicaSetRecStepView::AfterCreatePod((diff - 1) as nat),
2288.                                 ..state
2289.                             };
2290.                             (state_prime, Some(RequestView::KRequest(req)))
2291.                         } else {
2292.                             let diff = filtered_pods.len() - desired_replicas;
2293.                             let pod_name_or_none = filtered_pods[diff - 1].metadata.name;
2294.                             if pod_name_or_none.is_none() {
2295.                                 (error_state(state), None)
2296.                             } else {
2297.                                 let req = APIRequest::GetThenDeleteRequest(GetThenDeleteRequest {
2298.                                     key: ObjectRef {
2299.                                         kind: PodView::kind(),
2300.                                         name: pod_name_or_none.unwrap(),
2301.                                         namespace: namespace,
2302.                                     },
2303.                                     owner_ref: v_replica_set.controller_owner_ref(),
2304.                                 });
2305.                                 let state_prime = VReplicaSetReconcileState {
2306.                                     reconcile_step: VReplicaSetRecStepView::AfterDeletePod((diff - 1) as nat),
2307.                                     filtered_pods: Some(filtered_pods),
2308.                                     ..state
2309.                                 };
2310.                                 (state_prime, Some(RequestView::KRequest(req)))
2311.                             }
2312.                         }
2313.                     }
2314.                 }
2315.             }
2316.         },
2317.         VReplicaSetRecStepView::AfterCreatePod(diff) => {
2318.             let diff = *diff;
2319.             let predicate1 = (resp_o is Some &&
2320.                                 resp_o.unwrap() is KResponse &&
2321.                                 resp_o.unwrap().arrow_KResponse_0() is CreateResponse);
2322.             let predicate2 = resp_o.unwrap().arrow_KResponse_0().arrow_CreateResponse_0().res;
2323. 
2324.             if !(predicate1 && predicate2 is Ok) {
2325.                 (error_state(state), None)
2326.             } else if diff == 0 {
2327.                 let state_prime = VReplicaSetReconcileState {
2328.                     reconcile_step: VReplicaSetRecStepView::Done,
2329.                     ..state
2330.                 };
2331.                 (state_prime, None)
2332.             } else {
2333.                 let pod = make_pod(v_replica_set);
2334.                 let req = APIRequest::CreateRequest(CreateRequest {
2335.                     namespace: namespace,
2336.                     obj: pod.marshal(),
2337.                 });
2338.                 let state_prime = VReplicaSetReconcileState {
2339.                     reconcile_step: VReplicaSetRecStepView::AfterCreatePod((diff - 1) as nat),
2340.                     ..state
2341.                 };
2342.                 (state_prime, Some(RequestView::KRequest(req)))
2343.             }
2344.         },
2345.         VReplicaSetRecStepView::AfterDeletePod(diff) => {
2346.             let diff = *diff;
2347.             let predicate1 = {
2348.                 resp_o is Some && resp_o.unwrap() is KResponse
2349.                 && resp_o.unwrap().arrow_KResponse_0() is GetThenDeleteResponse
2350.             };
2351.             let predicate2 = resp_o.unwrap().arrow_KResponse_0().arrow_GetThenDeleteResponse_0().res;
2352. 
2353.             if !(predicate1 && predicate2 is Ok) {
2354.                 (error_state(state), None)
2355.             } else if diff == 0 {
2356.                 let state_prime = VReplicaSetReconcileState {
2357.                     reconcile_step: VReplicaSetRecStepView::Done,
2358.                     ..state
2359.                 };
2360.                 (state_prime, None)
2361.             } else {
2362.                 if state.filtered_pods.is_none() {
2363.                     (error_state(state), None)
2364.                 } else if diff > state.filtered_pods.unwrap().len() {
2365.                     (error_state(state), None)
2366.                 } else {
2367.                     let pod_name_or_none = state.filtered_pods.unwrap()[diff - 1].metadata.name;
2368.                     if pod_name_or_none.is_none() {
2369.                         (error_state(state), None)
2370.                     } else {
2371.                         let req = APIRequest::GetThenDeleteRequest(GetThenDeleteRequest {
2372.                             key: ObjectRef {
2373.                                 kind: PodView::kind(),
2374.                                 name: pod_name_or_none.unwrap(),
2375.                                 namespace: namespace,
2376.                             },
2377.                             owner_ref: v_replica_set.controller_owner_ref(),
2378.                         });
2379.                         let state_prime = VReplicaSetReconcileState {
2380.                             reconcile_step: VReplicaSetRecStepView::AfterDeletePod((diff - 1) as nat),
2381.                             ..state
2382.                         };
2383.                         (state_prime, Some(RequestView::KRequest(req)))
2384.                     }
2385.                 }
2386.             }
