2571. impl<State, Input, ActionInput, Output, Step> StateMachine<State, Input, ActionInput, Output, Step> {
2572. 
2573.     pub open spec fn next_result(self, input: Input, s: State) -> ActionResult<State, Output> {
2574.         if exists |step| (#[trigger] (self.step_to_action)(step).precondition)((self.action_input)(step, input), s) {
2575.             let witness_step = choose |step| (#[trigger] (self.step_to_action)(step).precondition)((self.action_input)(step, input), s);
2576.             let action = (self.step_to_action)(witness_step);
2577.             let action_input = (self.action_input)(witness_step, input);
2578.             ActionResult::Enabled((action.transition)(action_input, s).0, (action.transition)(action_input, s).1)
2579.         } else {
2580.             ActionResult::Disabled
2581.         }
2582.     }
