2970.         // Deletion fails.
2971.         (s, DeleteResponse{res: Err(delete_request_admission_check(req, s)->0)})
2972.     } else {
2973.         // Deletion succeeds.
2974.         let obj = s.resources[req.key];
2975.         if obj.metadata.finalizers is Some && obj.metadata.finalizers->0.len() > 0 {
2976.             // With the finalizer(s) in the object, we cannot immediately delete it from the key-value store.
2977.             // Instead, we set the deletion timestamp of this object.
2978.             // If the object already has a deletion timestamp, then skip.
2979.             //
2980.             // NOTE: Having finalizer(s) is not the only reason that a deletion is postponed. Having a graceful
2981.             // period set in the deletion option is another reason. Currently we do not model the graceful period
2982.             // option so we don't model how the API server checks whether a deletion should be graceful.
2983.             // However, even without a graceful period option, deleting a Pod can still be graceful depending on its
2984.             // spec content (see https://github.com/kubernetes/kubernetes/blob/v1.30.0/pkg/apis/core/types.go#L3256)
2985.             // because Pod implements CheckGracefulDelete (see https://github.com/kubernetes/kubernetes/blob/v1.30.0/pkg/registry/core/pod/strategy.go#L168).
2986.             // This is irrelevant to application controllers that do not manage pods, and acceptable for verifying
2987.             // low-level built-in controllers because they are supposed to treat terminating pods as non-existing pods.
2988.             if obj.metadata.deletion_timestamp is Some {
2989.                 // A deletion timestamp is already set so no need to bother it.
2990.                 (s, DeleteResponse{res: Ok(())})
2991.             } else {
2992.                 let stamped_obj_with_new_rv = obj.with_deletion_timestamp(deletion_timestamp())
2993.                                                  .with_resource_version(s.resource_version_counter);
2994.                 (APIServerState {
2995.                     // Here we use req.key, instead of stamped_obj.object_ref(), to insert to the map.
2996.                     // This is intended because using stamped_obj.object_ref() will require us to use
2997.                     // the invariant each_object_in_etcd_is_well_formed a lot more frequently:
2998.                     // we need this invariant to convince Verus that the stamped_obj is well formed
2999.                     // so the key we use to insert to the map is the same as req.key.
3000.                     resources: s.resources.insert(req.key, stamped_obj_with_new_rv),
3001.                     resource_version_counter: s.resource_version_counter + 1,
3002.                     ..s
3003.                 }, DeleteResponse{res: Ok(())})
3004.             }
3005.         } else {
3006.             // The object can be immediately removed from the key-value store.
3007.             //
3008.             // NOTE: In some very corner case, the API server *seems* to first updates the object (to update its finalizers)
3009.             // and then deletes the object immediately, which makes the entire Delete operation not atomic.
3010.             // However, this only happens in the orphan or foreground deletion mode, so we do not model this
3011.             // seemingly non-atomic behavior for now.
3012.             // For more details, see how the API server updates the object in the middle of handling deletion requests:
3013.             // https://github.com/kubernetes/kubernetes/blob/v1.30.0/staging/src/k8s.io/apiserver/pkg/registry/generic/registry/store.go#L1009
3014.             (APIServerState {
3015.                 resources: s.resources.remove(req.key),
3016.                 resource_version_counter: s.resource_version_counter + 1,
3017.                 ..s
3018.             }, DeleteResponse{res: Ok(())})
3019.         }
3020.     }
3021. }
