3030. pub open spec fn update_request_admission_check_helper(installed_types: InstalledTypes, name: StringView, namespace: StringView, obj: DynamicObjectView, s: APIServerState) -> Option<APIError> {
3031.     let key = ObjectRef {
3032.         kind: obj.kind,
3033.         namespace: namespace,
3034.         name: name,
3035.     };
3036.     if obj.metadata.name is None {
3037.         // Update fails because the name of the object is not provided
3038.         Some(APIError::BadRequest)
3039.     } else if name != obj.metadata.name->0 {
3040.         // Update fails because the name of the provided object
3041.         // does not match the name sent on the request
3042.         Some(APIError::BadRequest)
3043.     } else if obj.metadata.namespace is Some
3044.         && namespace != obj.metadata.namespace->0 {
3045.         // Update fails because the namespace of the provided object
3046.         // does not match the namespace sent on the request
3047.         Some(APIError::BadRequest)
3048.     } else if !unmarshallable_object(obj, installed_types) {
3049.         // Update fails because the provided object is not well formed
3050.         // TODO: should the error be BadRequest?
3051.         Some(APIError::BadRequest)
3052.     } else if !s.resources.contains_key(key) {
3053.         // Update fails because the object does not exist
3054.         // TODO: check AllowCreateOnUpdate() to see whether to support create-on-update
3055.         Some(APIError::ObjectNotFound)
3056.     } else if obj.metadata.resource_version is None
3057.         && !allow_unconditional_update(key.kind) {
3058.         // Update fails because the object does not provide a rv and unconditional update is not supported
3059.         Some(APIError::Invalid)
3060.     } else if obj.metadata.resource_version is Some
3061.         && obj.metadata.resource_version != s.resources[key].metadata.resource_version {
3062.         // Update fails because the object has a wrong rv
3063.         Some(APIError::Conflict)
3064.     } else if obj.metadata.uid is Some
3065.         && obj.metadata.uid != s.resources[key].metadata.uid {
3066.         // Update fails because the object has a wrong uid
3067.         Some(APIError::Conflict)
3068.     } else {
3069.         None
3070.     }
3071. }
