3209.             } else {
3210.                 // UpdateStatus succeeds.
3211.                 (APIServerState {
3212.                     resources: s.resources.insert(req.key(), updated_obj_with_new_rv),
3213.                     resource_version_counter: s.resource_version_counter + 1, // Advance the rv counter
3214.                     ..s
3215.                 }, UpdateStatusResponse{res: Ok(updated_obj_with_new_rv)})
3216.             }
3217.         }
3218.     }
3219. }
