3273. pub open spec fn handle_get_then_delete_request_msg(msg: Message, s: APIServerState) -> (APIServerState, Message)
3274.     recommends
3275.         msg.content.is_get_then_delete_request(),
3276. {
3277.     let req = msg.content.get_get_then_delete_request();
3278.     // Step 1: get the object
3279.     let get_req = GetRequest {
3280.         key: req.key
3281.     };
3282.     let get_resp = handle_get_request(get_req, s);
3283.     match get_resp.res {
3284.         Ok(_) => {
3285.             let current_obj = s.resources[req.key()];
3286.             // Step 2: if the object exists, perform a check using a predicate on object
3287.             // The predicate: Is the current object owned by req.owner_ref?
3288.             // TODO: the predicate should be provided by clients instead of the hardcoded one
3289.             if current_obj.metadata.owner_references_contains(req.owner_ref) {
3290.                 // Step 3: if the check passes, delete the object
3291.                 let delete_req = DeleteRequest {
3292.                     key: req.key,
3293.                     preconditions: None,
3294.                 };
3295.                 let (s_prime, delete_resp) = handle_delete_request(delete_req, s);
3296.                 (s_prime, form_get_then_delete_resp_msg(msg, GetThenDeleteResponse {res: delete_resp.res}))
3297.             } else {
3298.                 (s, form_get_then_delete_resp_msg(msg, GetThenDeleteResponse {res: Err(APIError::TransactionAbort)}))
3299.             }
3300.         }
3301.         Err(err) => (s, form_get_then_delete_resp_msg(msg, GetThenDeleteResponse {res: Err(err)}))
3302.     }
3303. }
