3305. pub open spec fn handle_get_then_update_request_msg(installed_types: InstalledTypes, msg: Message, s: APIServerState) -> (APIServerState, Message)
3306.     recommends
3307.         msg.content.is_get_then_update_request(),
3308. {
3309.     let req = msg.content.get_get_then_update_request();
3310.     // Step 1: get the object
3311.     let get_req = GetRequest {
3312.         key: req.key()
3313.     };
3314.     let get_resp = handle_get_request(get_req, s);
3315.     match get_resp.res {
3316.         Ok(_) => {
3317.             let current_obj = s.resources[req.key()];
3318.             // Step 2: if the object exists, perform a check using a predicate on object
3319.             // The predicate: Is the current object owned by req.owner_ref?
3320.             // TODO: the predicate should be provided by clients instead of the hardcoded one
3321.             if current_obj.metadata.owner_references_contains(req.owner_ref) {
3322.                 // Step 3: if the check passes, overwrite the object with the new one
3323.                 // Note that resource_version and uid comes from the current object to avoid conflict error
3324.                 let new_obj = DynamicObjectView {
3325.                     metadata: ObjectMetaView {
3326.                         resource_version: current_obj.metadata.resource_version,
3327.                         uid: current_obj.metadata.uid,
3328.                         ..req.obj.metadata
3329.                     },
3330.                     ..req.obj
3331.                 };
3332.                 let update_req = UpdateRequest {
3333.                     name: req.name,
3334.                     namespace: req.namespace,
3335.                     obj: new_obj,
3336.                 };
3337.                 let (s_prime, update_resp) = handle_update_request(installed_types, update_req, s);
3338.                 (s_prime, form_get_then_update_resp_msg(msg, GetThenUpdateResponse {res: update_resp.res}))
3339.             } else {
3340.                 (s, form_get_then_update_resp_msg(msg, GetThenUpdateResponse {res: Err(APIError::TransactionAbort)}))
3341.             }
3342.         }
3343.         Err(err) => (s, form_get_then_update_resp_msg(msg, GetThenUpdateResponse {res: Err(err)}))
3344.     }
3345. }
