3347. pub open spec fn transition_by_etcd(installed_types: InstalledTypes, msg: Message, s: APIServerState) -> (APIServerState, Message)
3348.     recommends
3349.         msg.content is APIRequest,
3350. {
3351.     match msg.content->APIRequest_0 {
3352.         APIRequest::GetRequest(_) => handle_get_request_msg(msg, s),
3353.         APIRequest::ListRequest(_) => handle_list_request_msg(msg, s),
3354.         APIRequest::CreateRequest(_) => handle_create_request_msg(installed_types, msg, s),
3355.         APIRequest::DeleteRequest(_) => handle_delete_request_msg(msg, s),
3356.         APIRequest::UpdateRequest(_) => handle_update_request_msg(installed_types, msg, s),
3357.         APIRequest::UpdateStatusRequest(_) => handle_update_status_request_msg(installed_types, msg, s),
3358.         APIRequest::GetThenDeleteRequest(_) => handle_get_then_delete_request_msg(msg, s),
3359.         APIRequest::GetThenUpdateRequest(_) => handle_get_then_update_request_msg(installed_types, msg, s),
3360.     }
3361. }
