3363. pub open spec fn handle_request(installed_types: InstalledTypes) -> APIServerAction {
3364.     Action {
3365.         precondition: |input: APIServerActionInput, s: APIServerState| {
3366.             &&& input.recv is Some
3367.             &&& input.recv->0.content is APIRequest
3368.         },
3369.         transition: |input: APIServerActionInput, s: APIServerState| {
3370.             let (s_prime, etcd_resp) = transition_by_etcd(installed_types, input.recv->0, s);
3371.             (s_prime, APIServerActionOutput {
3372.                 send: Multiset::singleton(etcd_resp)
3373.             })
3374.         },
3375.     }
3376. }
