3382.         },
3383.         actions: set![handle_request(installed_types)],
3384.         step_to_action: |step: APIServerStep| {
3385.             match step {
3386.                 APIServerStep::HandleRequest => handle_request(installed_types),
3387.             }
3388.         },
3389.         action_input: |step: APIServerStep, input: APIServerActionInput| {
3390.             input
3391.         }
3392.     }
3393. }
