3495. pub open spec fn continue_reconcile(model: ReconcileModel, controller_id: int) -> ControllerAction {
3496.     Action {
3497.         precondition: |input: ControllerActionInput, s: ControllerState| {
3498.             if input.scheduled_cr_key is Some {
3499.                 let cr_key = input.scheduled_cr_key->0;
3500. 
3501.                 &&& cr_key.kind == model.kind
3502.                 &&& s.ongoing_reconciles.contains_key(cr_key)
3503.                 &&& !(model.done)(s.ongoing_reconciles[cr_key].local_state)
3504.                 &&& !(model.error)(s.ongoing_reconciles[cr_key].local_state)
3505.                 &&& if s.ongoing_reconciles[cr_key].pending_req_msg is Some {
3506.                     &&& input.recv is Some
3507.                     &&& (input.recv->0.content is APIResponse || input.recv->0.content is ExternalResponse)
3508.                     &&& resp_msg_matches_req_msg(input.recv->0, s.ongoing_reconciles[cr_key].pending_req_msg->0)
3509.                 } else {
3510.                     input.recv is None
3511.                 }
3512.             } else {
3513.                 false
3514.             }
3515.         },
3516.         transition: |input: ControllerActionInput, s: ControllerState| {
3517.             let cr_key = input.scheduled_cr_key->0;
3518.             let reconcile_state = s.ongoing_reconciles[cr_key];
3519.             let resp_o = if input.recv is Some {
3520.                 if input.recv->0.content is APIResponse {
3521.                     Some(ResponseContent::KubernetesResponse(input.recv->0.content.arrow_APIResponse_0()))
3522.                 } else {
3523.                     Some(ResponseContent::ExternalResponse(input.recv->0.content.arrow_ExternalResponse_0()))
3524.                 }
3525.             } else {
3526.                 None
3527.             };
3528.             let (local_state_prime, req_o) = (model.transition)(reconcile_state.triggering_cr, resp_o, reconcile_state.local_state);
3529.             let (pending_req_msg, send, rpc_id_allocator_prime) = if req_o is Some {
3530.                 let pending_req_msg = match req_o->0 {
3531.                     RequestContent::KubernetesRequest(req) => {
3532.                         Some(controller_req_msg(controller_id, cr_key, input.rpc_id_allocator.allocate().1, req))
3533.                     },
3534.                     RequestContent::ExternalRequest(req) => {
3535.                         Some(controller_external_req_msg(controller_id, cr_key, input.rpc_id_allocator.allocate().1, req))
3536.                     }
3537.                 };
3538.                 (pending_req_msg, Multiset::singleton(pending_req_msg->0), input.rpc_id_allocator.allocate().0)
3539.             } else {
3540.                 (None, Multiset::empty(), input.rpc_id_allocator)
3541.             };
3542. 
3543.             let reconcile_state_prime = OngoingReconcile {
3544.                 pending_req_msg: pending_req_msg,
3545.                 local_state: local_state_prime,
3546.                 ..reconcile_state
3547.             };
3548.             let s_prime = ControllerState {
3549.                 ongoing_reconciles: s.ongoing_reconciles.insert(cr_key, reconcile_state_prime),
3550.                 ..s
3551.             };
3552.             let output = ControllerActionOutput {
3553.                 send: send,
3554.                 rpc_id_allocator: rpc_id_allocator_prime,
3555.             };
3556.             (s_prime, output)
3557.         }
3558.     }
3559. }
