1436.     pub open spec fn init(self) -> StatePred<ClusterState> {
1437.         |s: ClusterState| {
1438.             // The API server is initialized...
1439.             &&& (api_server(self.installed_types).init)(s.api_server)
1440.             // and the built-in controllers are initialized...
1441.             &&& (builtin_controllers().init)(())
1442.             // and the network is initialized...
1443.             &&& (network().init)(s.network)
1444.             // and message drop is enabled...
1445.             &&& s.req_drop_enabled
1446.             // and pod monkey is enabled...
1447.             &&& s.pod_monkey_enabled
1448.             // and for each controller...
1449.             &&& forall |key| #[trigger] self.controller_models.contains_key(key)
1450.                 ==> {
1451.                     let model = self.controller_models[key];
1452.                     // its internal state exists...
1453.                     &&& s.controller_and_externals.contains_key(key)
1454.                     // and is initialized...
1455.                     &&& (controller(model.reconcile_model, key).init)(s.controller_and_externals[key].controller)
1456.                     // and crash for this controller is enabled...
1457.                     &&& s.controller_and_externals[key].crash_enabled
1458.                     // and if the controller has an associated external system...
1459.                     &&& model.external_model is Some
1460.                         ==> {
1461.                             // the internal state of that external system exists...
1462.                             &&& s.controller_and_externals[key].external is Some
1463.                             // and is initialized.
1464.                             &&& (external(model.external_model->0).init)(s.controller_and_externals[key].external->0)
1465.                         }
1466.                 }
1467.         }
1468.     }
1469. 
1470.     pub open spec fn next(self) -> ActionPred<ClusterState> {
1471.         |s, s_prime: ClusterState| exists |step: Step| self.next_step(s, s_prime, step)
1472.     }
1473. 
1474.     pub open spec fn next_step(self, s: ClusterState, s_prime: ClusterState, step: Step) -> bool {
1475.         match step {
1476.             Step::APIServerStep(input) => self.api_server_next().forward(input)(s, s_prime),
1477.             Step::BuiltinControllersStep(input) => self.builtin_controllers_next().forward(input)(s, s_prime),
1478.             Step::ControllerStep(input) => self.controller_next().forward(input)(s, s_prime),
1479.             Step::ScheduleControllerReconcileStep(input) => self.schedule_controller_reconcile().forward(input)(s, s_prime),
1480.             Step::RestartControllerStep(input) => self.restart_controller().forward(input)(s, s_prime),
1481.             Step::DisableCrashStep(input) => self.disable_crash().forward(input)(s, s_prime),
1482.             Step::DropReqStep(input) => self.drop_req().forward(input)(s, s_prime),
1483.             Step::DisableReqDropStep => self.disable_req_drop().forward(())(s, s_prime),
1484.             Step::PodMonkeyStep(input) => self.pod_monkey_next().forward(input)(s, s_prime),
1485.             Step::DisablePodMonkeyStep => self.disable_pod_monkey().forward(())(s, s_prime),
1486.             Step::ExternalStep(input) => self.external_next().forward(input)(s, s_prime),
1487.             Step::StutterStep => self.stutter().forward(())(s, s_prime),
1488.         }
1489.     }
1490. 
1491.     pub open spec fn api_server_next(self) -> Action<ClusterState, Option<Message>, ()> {
1492.         let result = |input: Option<Message>, s: ClusterState| {
1493.             let host_result = self.api_server().next_result(
1494.                 APIServerActionInput{ recv: input },
1495.                 s.api_server
1496.             );
1497.             let msg_ops = MessageOps {
1498.                 recv: input,
1499.                 send: host_result->Enabled_1.send,
1500.             };
1501.             let network_result = network().next_result(msg_ops, s.network);
1502. 
1503.             (host_result, network_result)
1504.         };
1505.         Action {
1506.             precondition: |input: Option<Message>, s: ClusterState| {
1507.                 &&& received_msg_destined_for(input, HostId::APIServer)
1508.                 &&& result(input, s).0 is Enabled
1509.                 &&& result(input, s).1 is Enabled
1510.             },
1511.             transition: |input: Option<Message>, s: ClusterState| {
1512.                 let (host_result, network_result) = result(input, s);
1513.                 (ClusterState {
1514.                     api_server: host_result->Enabled_0,
1515.                     network: network_result->Enabled_0,
1516.                     ..s
1517.                 }, ())
1518.             },
1519.         }
1520.     }
1521. 
1522.     pub open spec fn builtin_controllers_next(self) -> Action<ClusterState, (BuiltinControllerChoice, ObjectRef), ()> {
1523.         let result = |input: (BuiltinControllerChoice, ObjectRef), s: ClusterState| {
1524.             let host_result = self.builtin_controllers().next_result(
1525.                 BuiltinControllersActionInput {
1526.                     choice: input.0,
1527.                     key: input.1,
1528.                     rpc_id_allocator: s.rpc_id_allocator,
1529.                     resources: s.api_server.resources,
1530.                 },
1531.                 ()
1532.             );
1533.             let msg_ops = MessageOps {
1534.                 recv: None,
1535.                 send: host_result->Enabled_1.send,
1536.             };
1537.             let network_result = network().next_result(msg_ops, s.network);
1538. 
1539.             (host_result, network_result)
1540.         };
1541.         Action {
1542.             precondition: |input: (BuiltinControllerChoice, ObjectRef), s: ClusterState| {
1543.                 &&& result(input, s).0 is Enabled
1544.                 &&& result(input, s).1 is Enabled
1545.             },
1546.             transition: |input: (BuiltinControllerChoice, ObjectRef), s: ClusterState| {
1547.                 let (host_result, network_result) = result(input, s);
1548.                 (ClusterState {
1549.                     network: network_result->Enabled_0,
1550.                     rpc_id_allocator: host_result->Enabled_1.rpc_id_allocator,
1551.                     ..s
1552.                 }, ())
1553.             },
1554.         }
1555.     }
1556. 
1557.     pub open spec fn controller_next(self) -> Action<ClusterState, (int, Option<Message>, Option<ObjectRef>), ()> {
1558.         Action {
1559.             precondition: |input: (int, Option<Message>, Option<ObjectRef>), s: ClusterState| {
1560.                 let controller_id = input.0;
1561.                 let chosen_action = self.chosen_controller_next(controller_id);
1562.                 (chosen_action.precondition)((input.1, input.2), s)
1563.             },
1564.             transition: |input: (int, Option<Message>, Option<ObjectRef>), s: ClusterState| {
1565.                 let controller_id = input.0;
1566.                 let chosen_action = self.chosen_controller_next(controller_id);
1567.                 (chosen_action.transition)((input.1, input.2), s)
1568.             },
1569.         }
1570.     }
1571. 
1572.     pub open spec fn chosen_controller_next(self, controller_id: int) -> Action<ClusterState, (Option<Message>, Option<ObjectRef>), ()> {
1573.         let result = |input: (Option<Message>, Option<ObjectRef>), s: ClusterState| {
1574.             let host_result = self.controller(controller_id).next_result(
1575.                 ControllerActionInput{recv: input.0, scheduled_cr_key: input.1, rpc_id_allocator: s.rpc_id_allocator},
1576.                 s.controller_and_externals[controller_id].controller
1577.             );
1578.             let msg_ops = MessageOps {
1579.                 recv: input.0,
1580.                 send: host_result->Enabled_1.send,
1581.             };
1582.             let network_result = network().next_result(msg_ops, s.network);
1583. 
1584.             (host_result, network_result)
1585.         };
1586.         Action {
1587.             precondition: |input: (Option<Message>, Option<ObjectRef>), s: ClusterState| {
1588.                 &&& self.controller_models.contains_key(controller_id)
1589.                 &&& input.1 is Some
1590.                 &&& received_msg_destined_for(input.0, HostId::Controller(controller_id, input.1->0))
1591.                 &&& result(input, s).0 is Enabled
1592.                 &&& result(input, s).1 is Enabled
1593.             },
1594.             transition: |input: (Option<Message>, Option<ObjectRef>), s: ClusterState| {
1595.                 let (host_result, network_result) = result(input, s);
1596.                 let controller_and_external_state_prime = ControllerAndExternalState {
1597.                     controller: host_result->Enabled_0,
1598.                     ..s.controller_and_externals[controller_id]
1599.                 };
1600.                 (ClusterState {
1601.                     controller_and_externals: s.controller_and_externals.insert(controller_id, controller_and_external_state_prime),
1602.                     network: network_result->Enabled_0,
1603.                     rpc_id_allocator: host_result->Enabled_1.rpc_id_allocator,
1604.                     ..s
1605.                 }, ())
1606.             },
1607.         }
