1935.             APIResponse::GetThenUpdateResponse(_) => req_msg.content->APIRequest_0 is GetThenUpdateRequest,
1936.         }
1937.     }
1938.     ||| {
1939.         &&& resp_msg.content is ExternalResponse
1940.         &&& req_msg.content is ExternalRequest
1941.         &&& resp_msg.dst == req_msg.src
1942.         &&& resp_msg.src == req_msg.dst
