2863. pub open spec fn create_request_admission_check(installed_types: InstalledTypes, req: CreateRequest, s: APIServerState) -> Option<APIError> {
2864.     if req.obj.metadata.name is None && req.obj.metadata.generate_name is None {
2865.         // Creation fails because neither the name nor the generate_name of the provided object is provided
2866.         Some(APIError::Invalid)
2867.     } else if req.obj.metadata.namespace is Some && req.namespace != req.obj.metadata.namespace->0 {
2868.         // Creation fails because the namespace of the provided object does not match the namespace sent on the request
2869.         Some(APIError::BadRequest)
2870.     } else if !unmarshallable_object(req.obj, installed_types) {
2871.         // Creation fails because the provided object is not well formed
2872.         Some(APIError::BadRequest) // TODO: should the error be BadRequest?
2873.     } else if req.obj.metadata.name is Some && s.resources.contains_key(req.obj.with_namespace(req.namespace).object_ref()) {
2874.         // Creation fails because the object has a name and it already exists
2875.         Some(APIError::ObjectAlreadyExists)
2876.     } else {
2877.         None
2878.     }
2879. }
