2893. #[verifier(inline)]
2894. pub open spec fn handle_create_request(installed_types: InstalledTypes, req: CreateRequest, s: APIServerState) -> (APIServerState, CreateResponse) {
2895.     if create_request_admission_check(installed_types, req, s) is Some {
2896.         // Creation fails.
2897.         (s, CreateResponse{res: Err(create_request_admission_check(installed_types, req, s)->0)})
2898.     } else {
2899.         let created_obj = DynamicObjectView {
2900.             kind: req.obj.kind,
2901.             metadata: ObjectMetaView {
2902.                 // Set name for new object if name is not provided, here we generate
2903.                 // a unique name. The uniqueness is guaranteed by generated_name_is_unique.
2904.                 name: if req.obj.metadata.name is Some {
2905.                     req.obj.metadata.name
2906.                 } else {
2907.                     Some(generate_name(s))
2908.                 },
2909.                 namespace: Some(req.namespace), // Set namespace for new object
2910.                 resource_version: Some(s.resource_version_counter), // Set rv for new object
2911.                 uid: Some(s.uid_counter), // Set uid for new object
2912.                 deletion_timestamp: None, // Unset deletion timestamp for new object
2913.                 ..req.obj.metadata
2914.             },
2915.             spec: req.obj.spec,
2916.             status: marshalled_default_status(req.obj.kind, installed_types), // Overwrite the status with the default one
2917.         };
2918.         if s.resources.contains_key(created_obj.object_ref()) {
2919.             // Note 1: You might find this branch redundant since we already have
2920.             // generated_name_is_unique which guarantees that the created_obj's
2921.             // key is different from any existing keys even if name was not provided.
2922.             // But we still add this branch just to avoid calling generated_name_is_unique
2923.             // when we want to show that create without a provided name does not override
2924.             // an existing object when writing proofs.
2925.             //
2926.             // Note 2: Adding this branch also means that if we want to prove the object
2927.             // is eventually created by a create request without the name provided,
2928.             // we need to explicitly call generated_name_is_unique to show that
2929.             // we do not fall into this branch.
2930.             (s, CreateResponse{res: Err(APIError::ObjectAlreadyExists)})
2931.         } else if created_object_validity_check(created_obj, installed_types) is Some {
2932.             // Creation fails.
2933.             (s, CreateResponse{res: Err(created_object_validity_check(created_obj, installed_types)->0)})
2934.         } else {
2935.             // Creation succeeds.
2936.             (APIServerState {
2937.                 resources: s.resources.insert(created_obj.object_ref(), created_obj),
2938.                 uid_counter: s.uid_counter + 1,
2939.                 resource_version_counter: s.resource_version_counter + 1,
2940.                 ..s
2941.             }, CreateResponse{res: Ok(created_obj)})
2942.         }
2943.     }
2944. }
