2946. pub open spec fn delete_request_admission_check(req: DeleteRequest, s: APIServerState) -> Option<APIError> {
2947.     if !s.resources.contains_key(req.key) {
2948.         // Deletion fails because the object does not exist
2949.         Some(APIError::ObjectNotFound)
2950.     } else if req.preconditions is Some {
2951.         let preconditions = req.preconditions->0;
2952.         if preconditions.uid is Some && preconditions.uid != s.resources[req.key].metadata.uid {
2953.             // Deletion fails because the uid of the object does not match the uid in the precondition
2954.             Some(APIError::Conflict)
2955.         } else if preconditions.resource_version is Some && preconditions.resource_version != s.resources[req.key].metadata.resource_version {
2956.             // Deletion fails because the resource version of the object does not match the resource version in the precondition
2957.             Some(APIError::Conflict)
2958.         } else {
2959.             None
2960.         }
2961.     } else {
2962.         None
2963.     }
2964. }
