3077. pub open spec fn updated_object(req: UpdateRequest, old_obj: DynamicObjectView) -> DynamicObjectView {
3078.     let updated_obj = DynamicObjectView {
3079.         kind: req.obj.kind,
3080.         metadata: ObjectMetaView {
3081.             namespace: Some(req.namespace), // Overwrite namespace since it might not be provided
3082.             resource_version: old_obj.metadata.resource_version, // Overwrite rv since it might not be provided
3083.             uid: old_obj.metadata.uid, // Overwrite uid since it might not be provided
3084.             deletion_timestamp: old_obj.metadata.deletion_timestamp, // Ignore any change to deletion_timestamp
3085.             ..req.obj.metadata
3086.         },
3087.         spec: req.obj.spec,
3088.         status: old_obj.status, // Ignore any change to status
3089.     };
3090.     updated_obj
3091. }
