3093. pub open spec fn updated_object_validity_check(updated_obj: DynamicObjectView, old_obj: DynamicObjectView, installed_types: InstalledTypes) -> Option<APIError> {
3094.     if metadata_validity_check(updated_obj) is Some {
3095.         metadata_validity_check(updated_obj)
3096.     } else if metadata_transition_validity_check(updated_obj, old_obj) is Some {
3097.         metadata_transition_validity_check(updated_obj, old_obj)
3098.     } else if object_validity_check(updated_obj, installed_types) is Some {
3099.         object_validity_check(updated_obj, installed_types)
3100.     } else if object_transition_validity_check(updated_obj, old_obj, installed_types) is Some {
3101.         object_transition_validity_check(updated_obj, old_obj, installed_types)
3102.     } else {
3103.         None
3104.     }
3105. }
