3107. #[verifier(inline)]
3108. pub open spec fn handle_update_request(installed_types: InstalledTypes, req: UpdateRequest, s: APIServerState) -> (APIServerState, UpdateResponse) {
3109.     if update_request_admission_check(installed_types, req, s) is Some {
3110.         // Update fails.
3111.         (s, UpdateResponse{res: Err(update_request_admission_check(installed_types, req, s)->0)})
3112.     } else {
3113.         let old_obj = s.resources[req.key()];
3114.         let updated_obj = updated_object(req, old_obj);
3115.         if updated_obj == old_obj {
3116.             // Update is a noop because there is nothing to update
3117.             // so the resource version counter does not increase here,
3118.             // and the resource version of this object remains the same.
3119.             (s, UpdateResponse{res: Ok(old_obj)})
3120.         } else {
3121.             // Update changes something in the object (either in spec or metadata), so we set it a newer resource version,
3122.             // which is the current rv counter.
3123.             let updated_obj_with_new_rv = updated_obj.with_resource_version(s.resource_version_counter);
3124.             if updated_object_validity_check(updated_obj_with_new_rv, old_obj, installed_types) is Some {
3125.                 // Update fails.
3126.                 (s, UpdateResponse{res: Err(updated_object_validity_check(updated_obj_with_new_rv, old_obj, installed_types)->0)})
3127.             } else {
3128.                 // Update succeeds.
3129.                 if updated_obj_with_new_rv.metadata.deletion_timestamp is None
3130.                     || (updated_obj_with_new_rv.metadata.finalizers is Some
3131.                         && updated_obj_with_new_rv.metadata.finalizers->0.len() > 0)
3132.                 {
3133.                     // The regular update case, where the object has no deletion timestamp set
3134.                     // or has at least one finalizer.
3135.                     (APIServerState {
3136.                         resources: s.resources.insert(req.key(), updated_obj_with_new_rv),
3137.                         resource_version_counter: s.resource_version_counter + 1, // Advance the rv counter
3138.                         ..s
3139.                     }, UpdateResponse{res: Ok(updated_obj_with_new_rv)})
3140.                 } else {
3141.                     // The delete-during-update case, where the update removes the finalizers from
3142.                     // the object that has a deletion timestamp, so the object needs to be deleted now.
3143.                     //
3144.                     // NOTE: in the actual implementation, when handling an update request,
3145.                     // the API server first applies the update to the object in the key-value store,
3146.                     // then checks whether the object can be deleted.
3147.                     // If so, it continues to delete the object from the key-value store before replying
3148.                     // to the update request.
3149.                     // This means that there is a super short window where the object has been updated in the store
3150.                     // (with a deletion timestamp and without any finalizer), but has not been deleted yet.
3151.                     // This behavior, strictly speaking, makes the entire Update operation not atomic.
3152.                     // We choose to still model the Update operation as an atomic step for simplicity.
3153.                     // This design choice does not affect the correctness of the controller that issues Update
3154.                     // in a blocking manner because the controller will never observe this intermediate state between
3155.                     // the update and deletion.
3156.                     // More generally speaking, this modeling won't affect the correctness of any controller that
3157.                     // treats a terminating object without finalizers as a non-existing object --- a good practice
3158.                     // controllers should follow.
3159.                     //
3160.                     // NOTE: the API server should also check whether the deletion grace period in the metadata
3161.                     // is set to 0 before deleting the object in case of graceful deletion
3162.                     // (see https://github.com/kubernetes/kubernetes/blob/v1.30.0/staging/src/k8s.io/apiserver/pkg/registry/generic/registry/store.go#L533).
