3166.                         resource_version_counter: s.resource_version_counter + 1, // Advance the rv counter
3167.                         ..s
3168.                     }, UpdateResponse{res: Ok(updated_obj_with_new_rv)})
3169.                 }
3170.             }
3171.         }
3172.     }
