3189. #[verifier(inline)]
3190. pub open spec fn handle_update_status_request(installed_types: InstalledTypes, req: UpdateStatusRequest, s: APIServerState) -> (APIServerState, UpdateStatusResponse) {
3191.     if update_status_request_admission_check(installed_types, req, s) is Some {
3192.         // UpdateStatus fails.
3193.         (s, UpdateStatusResponse{res: Err(update_status_request_admission_check(installed_types, req, s)->0)})
3194.     } else {
3195.         let old_obj = s.resources[req.key()];
3196.         let updated_obj = status_updated_object(req, old_obj);
3197.         if updated_obj == old_obj {
3198.             // UpdateStatus is a noop because there is nothing to update
3199.             // so the resource version counter does not increase here,
3200.             // and the resource version of this object remains the same.
3201.             (s, UpdateStatusResponse{res: Ok(old_obj)})
3202.         } else {
3203.             // UpdateStatus changes something in the object (in status), so we set it a newer resource version,
3204.             // which is the current rv counter.
3205.             let updated_obj_with_new_rv = updated_obj.with_resource_version(s.resource_version_counter);
3206.             if updated_object_validity_check(updated_obj_with_new_rv, old_obj, installed_types) is Some {
3207.                 // UpdateStatus fails.
3208.                 (s, UpdateStatusResponse{res: Err(updated_object_validity_check(updated_obj_with_new_rv, old_obj, installed_types)->0)})
3209.             } else {
3210.                 // UpdateStatus succeeds.
3211.                 (APIServerState {
3212.                     resources: s.resources.insert(req.key(), updated_obj_with_new_rv),
3213.                     resource_version_counter: s.resource_version_counter + 1, // Advance the rv counter
3214.                     ..s
3215.                 }, UpdateStatusResponse{res: Ok(updated_obj_with_new_rv)})
3216.             }
3217.         }
3218.     }
3219. }
