3397. pub open spec fn run_garbage_collector() -> BuiltinControllersAction {
3398.     Action {
3399.         precondition: |input: BuiltinControllersActionInput, s: ()| {
3400.             let resources = input.resources;
3401.             let key = input.key;
3402.             let owner_references = resources[key].metadata.owner_references->0;
3403.             // The garbage collector is chosen by the top level state machine
3404.             &&& input.choice is GarbageCollector
3405.             // The object exists in the cluster state
3406.             &&& resources.contains_key(input.key)
3407.             // and it has at least one owner reference
3408.             &&& resources[key].metadata.owner_references is Some
3409.             &&& resources[key].metadata.owner_references->0.len() > 0
3410.             // The garbage collector decides whether to delete an object by checking its owner references,
3411.             // it deletes the object if for each owner reference...
3412.             &&& forall |i| #![trigger owner_references[i]] 0 <= i < owner_references.len() ==> {
3413.                 // the referred owner object does not exist in the cluster state
3414.                 ||| !resources.contains_key(owner_reference_to_object_reference(owner_references[i], key.namespace))
3415.                 // or it exists but has a different uid
3416.                 // (which means the actual owner was deleted and another object with the same name gets created again)
3417.                 ||| resources[owner_reference_to_object_reference(owner_references[i], key.namespace)].metadata.uid != Some(owner_references[i].uid)
3418.             }
3419.         },
3420.         transition: |input: BuiltinControllersActionInput, s: ()| {
3421.             // GC set the preconditions to the object's uid in its delete request
3422.             // See https://github.com/kubernetes/kubernetes/blob/v1.30.0/pkg/controller/garbagecollector/operations.go#L52-L61
3423.             let preconditions = PreconditionsView {
3424.                 uid: input.resources[input.key].metadata.uid,
3425.                 resource_version: None,
3426.             };
3427.             let delete_req_msg = built_in_controller_req_msg(
3428.                 input.rpc_id_allocator.allocate().1, delete_req_msg_content(input.key, Some(preconditions))
3429.             );
3430.             let output = BuiltinControllersActionOutput {
3431.                 send: Multiset::singleton(delete_req_msg),
3432.                 rpc_id_allocator: input.rpc_id_allocator.allocate().0,
3433.             };
3434.             ((), output)
3435.         },
3436.     }
3437. }
