3467.             &&& s.scheduled_reconciles.contains_key(input.scheduled_cr_key->0)
3468.             &&& input.recv is None
3469.             &&& !s.ongoing_reconciles.contains_key(input.scheduled_cr_key->0)
3470.         },
3471.         transition: |input: ControllerActionInput, s: ControllerState| {
3472.             let cr_key = input.scheduled_cr_key->0;
3473.             let (new_allocator, reconcile_id) = s.reconcile_id_allocator.allocate();
3474.             let initialized_ongoing_reconcile = OngoingReconcile {
3475.                 triggering_cr: s.scheduled_reconciles[cr_key],
3476.                 pending_req_msg: None,
3477.                 local_state: (model.init)(),
3478.                 reconcile_id: reconcile_id
3479.             };
3480.             let s_prime = ControllerState {
3481.                 ongoing_reconciles: s.ongoing_reconciles.insert(cr_key, initialized_ongoing_reconcile),
3482.                 scheduled_reconciles: s.scheduled_reconciles.remove(cr_key),
3483.                 reconcile_id_allocator: new_allocator,
3484.                 ..s
3485.             };
3486.             let output = ControllerActionOutput {
3487.                 send: Multiset::empty(),
3488.                 rpc_id_allocator: input.rpc_id_allocator,
3489.             };
