3539.             } else {
3540.                 (None, Multiset::empty(), input.rpc_id_allocator)
3541.             };
3542. 
3543.             let reconcile_state_prime = OngoingReconcile {
3544.                 pending_req_msg: pending_req_msg,
3545.                 local_state: local_state_prime,
