3670. pub open spec fn deliver() -> Action<NetworkState, MessageOps, ()> {
3671.     Action {
3672.         precondition: |msg_ops: MessageOps, s: NetworkState| {
3673.             msg_ops.recv is Some ==> s.in_flight.contains(msg_ops.recv->0)
3674.         },
3675.         transition: |msg_ops: MessageOps, s: NetworkState| {
3676.             if msg_ops.recv is Some {
3677.                 let s_prime = NetworkState {
3678.                     in_flight: s.in_flight.remove(msg_ops.recv->0).add(msg_ops.send)
3679.                 };
3680.                 (s_prime, ())
3681.             } else {
3682.                 let s_prime = NetworkState {
3683.                     in_flight: s.in_flight.add(msg_ops.send)
3684.                 };
3685.                 (s_prime, ())
3686.             }
3687.         },
3688.     }
3689. }
