4213. 
4214. pub open spec fn installed_reconcile_model<R, S, K, EReq, EResp>() -> ReconcileModel
4215.     where
4216.         R: Reconciler<S, K, EReq, EResp>,
4217.         K: CustomResourceView,
4218.         S: Marshallable,
4219.         EReq: Marshallable,
4220.         EResp: Marshallable,
4221. {
4222.     ReconcileModel {
4223.         kind: K::kind(),
4224.         init: || R::reconcile_init_state().marshal(),
4225.         transition: |obj, resp_o, s| {
4226.             let obj_um = K::unmarshal(obj)->Ok_0;
4227.             let resp_o_um = match resp_o {
4228.                 None => None,
4229.                 Some(resp) => Some(match resp {
4230.                     ResponseContent::KubernetesResponse(api_resp) => ResponseView::<EResp>::KResponse(api_resp),
4231.                     ResponseContent::ExternalResponse(ext_resp) => ResponseView::<EResp>::ExternalResponse(EResp::unmarshal(ext_resp)->Ok_0),
4232.                 })
4233.             };
4234.             let s_um = S::unmarshal(s)->Ok_0;
4235.             let (s_prime_um, req_o_um) = R::reconcile_core(obj_um, resp_o_um, s_um);
4236.             (s_prime_um.marshal(), match req_o_um {
4237.                 None => None,
4238.                 Some(req) => Some(match req {
