         actions: set![handle_external_request(model)],
         step_to_action: |step: ExternalStep| {
             match step {
                 ExternalStep::HandleExternalRequest => handle_external_request(model),
             }
         },
         action_input: |step: ExternalStep, input: ExternalActionInput| {
             input
         }
     }
 }


